    $(document).ready(function () {
        // 아코디언 기능 추가 (한 개만 열리도록)
        $("#snb li.child_1depth > a").on("click", function (e) {
            const $li = $(this).parent("li");
            const $submenu = $li.children("ul");
            const $icon = $(this).find("i");

            if ($submenu.length === 0) return; // 서브메뉴가 없으면 무시

            e.preventDefault();               // 링크 이동 방지

            // 1) 현재 클릭한 메뉴가 닫혀 있는 상태라면,
            if (!$submenu.is(":visible")) {
                // └> 다른 열려 있는 메뉴들 모두 닫기
                $("#snb li.child_1depth").not($li).each(function () {
                    const $otherLi = $(this);
                    const $otherSubmenu = $otherLi.children("ul");
                    const $otherIcon = $otherLi.find("a > i");
                    if ($otherSubmenu.is(":visible")) {
                        $otherSubmenu.slideUp(200);
