            alert('이 브라우저에서는 복사 기능이 지원되지 않습니다.');
        }

        $url.remove();
    })


});

$(document).ready(function(){
    var hideOverlayTimer;

    function showOverlay() {
        clearTimeout(hideOverlayTimer);
        $('#gnb-overlay').show();
    }

    function hideOverlayWithDelay() {
        clearTimeout(hideOverlayTimer);
        hideOverlayTimer = setTimeout(function(){
            if ($('.menu-area-box:visible').length === 0) {
                $('#gnb-overlay').hide();
            }
        }, 0);
    }

    $('#gnb ul li.child_1depth').on('mouseenter', function(){
        showOverlay();
    }).on('mouseleave', function(){
        hideOverlayWithDelay();
    });

    $('.menu-area-box').on('mouseenter', function(){
        showOverlay();
    }).on('mouseleave', function(){
        hideOverlayWithDelay();
    });

    $('.header-logo, #gnb-btn').on('mouseenter', function(){
        hideOverlayWithDelay();
    });

    $('#gnb').on('mouseleave', function(){
        hideOverlayWithDelay();
    });

});

